const ctx = $('When Executed by Parent').first().json;
const channelItem = ($input.first().json.items || [])[0];
const uploadsPlaylistId = channelItem && channelItem.contentDetails
  && channelItem.contentDetails.relatedPlaylists
  && channelItem.contentDetails.relatedPlaylists.uploads;

if (!uploadsPlaylistId) {
  return [{ json: { ...ctx, uploadsPlaylistId: null, skipped: true, reason: 'Channel not found or has no uploads playlist' } }];
}

return [{ json: { ...ctx, uploadsPlaylistId } }];

const ctx = $('Extract uploads playlist id').first().json;
const items = $input.first().json.items || [];
const videoIds = items
  .map(it => it.contentDetails && it.contentDetails.videoId)
  .filter(Boolean);

if (!videoIds.length) {
  return [{ json: { ...ctx, videoIds: null, skipped: true, reason: 'No uploaded videos found' } }];
}

// videos.list accepts up to 50 ids per call, same limit as playlistItems.maxResults above.
return [{ json: { ...ctx, videoIds: videoIds.join(',') } }];

// ISO 8601 duration (e.g. "PT1M45S") -> seconds. YouTube's own Shorts definition
// also considers aspect ratio, but duration is the reliable signal available here.
// Threshold is 180s (3 min), not 60s -- YouTube expanded the Shorts max length
// from 60s to 3 minutes in late 2024.
function durationSeconds(iso) {
  const m = /^PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/.exec(iso || '');
  if (!m) return 0;
  const [, h, min, s] = m;
  return Number(h || 0) * 3600 + Number(min || 0) * 60 + Number(s || 0);
}

const ctx = $('Extract video IDs').first().json;
const items = $input.first().json.items || [];

return items.map(v => ({
  json: {
    platform: 'YouTube',
    channel: ctx.channel,
    account_id: ctx.account_id,
    likes_label: ctx.likes_label || 'Likes',
    id: String(v.id),
    title: (v.snippet && v.snippet.title || 'YouTube Video').split('\n')[0].slice(0, 60),
    type: durationSeconds(v.contentDetails && v.contentDetails.duration) <= 180 ? 'Short' : 'Video',
    views: v.statistics && v.statistics.viewCount != null ? Number(v.statistics.viewCount) : null,
    likes: v.statistics && v.statistics.likeCount != null ? Number(v.statistics.likeCount) : null,
    comments: v.statistics && v.statistics.commentCount != null ? Number(v.statistics.commentCount) : null,
    shares: null,
    permalink: 'https://www.youtube.com/watch?v=' + v.id,
    created_at: (v.snippet && v.snippet.publishedAt) || null,
    insights_ok: !!(v.statistics && v.statistics.viewCount != null),
  },
}));

// This sub-workflow has 3 possible terminal points (two IF-node "no data"
// dead ends, plus the normal success path) -- each carries different
// pairedItem lineage. The parent's Execute Workflow node only has ONE
// input, so reconciling multiple distinct terminal branches back to it can
// crash n8n's engine (assignPairedItems), same root cause as the Facebook
// Merge-node bug. Funneling everything through one shared node with
// pairedItem flattened to a plain 0 avoids ever exporting an ambiguous
// reference.
return $input.all().map(item => ({ json: item.json, pairedItem: 0 }));
